class Solution {
    static const int INF = 100000000;
    array<int, 2> dfs(TreeNode* node) {
        if (!node->left && !node->right) {
            if (node->val <= 1) return {node->val == 0 ? 0 : 1, node->val == 1 ? 0 : 1};
        }
        if (node->val == 5) {
            auto child = dfs(node->left ? node->left : node->right);
            return {child[1], child[0]};
        }
        auto a = dfs(node->left), b = dfs(node->right);
        array<int, 2> result = {INF, INF};
        for (int x = 0; x <= 1; ++x) for (int y = 0; y <= 1; ++y) {
            int z = node->val == 2 ? (x | y) : node->val == 3 ? (x & y) : (x ^ y);
            result[z] = min(result[z], a[x] + b[y]);
        }
        return result;
    }
public:
    int minimumFlips(TreeNode* root, bool result) { return dfs(root)[result]; }
};
